from requests import models
from requests.structures import _SupportsRead
import requests.models as m
import requests.structures as s

# Mock requests.models and requests.structures for testing
class MockModels:
    @staticmethod
    def _encode_files(files, data):
        print(f"Mock _encode_files called with files: {files}, data: {data}")
        return b"encoded_body", "multipart/form-data"

class MockStructures:
    def __init__(self):
        self.supports_read = False
    def supports_read(self):
        return self.supports_read

class MockRequest:
    def __init__(self, models=MockModels(), structures=MockStructures()):
        self.models = models
        self.structures = structures

    def __getattr__(self, name):
        return getattr(self.models, name)

    def __getitem__(self, key):
        return self.models[key]

    def __iter__(self):
        return iter(self.models)

def test_encode_files_with_raw_data():
    req = MockRequest()
    req.raw_data = b"some_data"
    req.files = {"file": b"some_file_data"}
    req.data = {"field": "value"}

    body, content_type = req._encode_files(req.files, req.raw_data)
    assert body == b"encoded_body"
    assert content_type == "multipart/form-data"

def test_encode_files_without_raw_data():
    req = MockRequest()
    req.files = {"file": b"some_file_data"}
    req.data = {"field": "value"}
    req.raw_data = None

    body, content_type = req._encode_files(req.files, req.raw_data)
    assert body == b"encoded_body"
    assert content_type == "multipart/form-data"

def test_encode_files_with_raw_data_and_dict():
    req = MockRequest()
    req.files = {"file": b"some_file_data"}
    req.raw_data = b"some_data"
    req.data = {"field": "value"}

    body, content_type = req._encode_files(req.files, req.raw_data)
    assert body == b"encoded_body"
    assert content_type == "multipart/form-data"

def test_encode_files_without_files_and_raw_data():
    req = MockRequest()
    req.files = None
    req.raw_data = b"some_data"
    req.data = {"field": "value"}

    with pytest.raises(ValueError, match="Files must be provided."):
        req._encode_files(req.files, req.raw_data)

def test_encode_files_without_files_and_no_raw_data():
    req = MockRequest()
    req.files = None
    req.raw_data = None
    req.data = {"field": "value"}

    body, content_type = req._encode_files(req.files, req.raw_data)
    assert body == b"encoded_body"
    assert content_type == "multipart/form-data"

def test_encode_files_with_raw_data_and_dict_no_files():
    req = MockRequest()
    req.files = None
    req.raw_data = b"some_data"
